import java.util.*;

class Solution {
    public int minAddToMakeValid(String s) {
        int open = 0, insert = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') open++;
            else if (open > 0) open--;   // matches an earlier '('
            else insert++;               // needs an inserted '(' before it
        }
        return insert + open;            // each leftover '(' needs a ')'
    }
}

